import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"Vim","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/Vim.md","filePath":"必学工具/Vim.md","lastUpdated":1792430298000}'),i={name:"必学工具/Vim.md"};function r(l,e,c,n,h,m){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="vim" tabindex="-1">Vim <a class="header-anchor" href="#vim" aria-label="Permalink to &quot;Vim&quot;">​</a></h1><blockquote><p>终端里的编辑器之王。在服务器上改配置、在靶场里快速编辑、在无图形界面环境工作时，Vim 是最可靠的伙伴。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>SSH 到远程服务器 / 靶机后，常用的编辑工具就是 Vim；</li><li>习惯 Vim 后编辑效率极高（但需要刻意练习初始阶段）。</li></ul><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><ol><li>终端输入 <code>vimtutor</code>，官方互动教程，约 30 分钟过一遍；</li><li>掌握模式概念：<strong>普通模式（Normal）/ 插入模式（Insert）/ 命令行模式</strong>；</li><li>记住最常用的几个操作即可开始，别追求「键位全背」。</li></ol><h2 id="核心操作速查" tabindex="-1">核心操作速查 <a class="header-anchor" href="#核心操作速查" aria-label="Permalink to &quot;核心操作速查&quot;">​</a></h2><ul><li><code>i</code> 插入、<code>Esc</code> 回到普通模式</li><li><code>:w</code> 保存、<code>:q</code> 退出、<code>:wq</code> 保存退出、<code>:q!</code> 放弃修改退出</li><li><code>dd</code> 删行、<code>yy</code> 复制行、<code>p</code> 粘贴</li><li><code>/keyword</code> 搜索、<code>n</code> 下一个匹配</li><li><code>gg</code> 文件开头、<code>G</code> 文件末尾</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>vimtutor</code></td><td>内置教程</td><td>最好的入门方式</td></tr><tr><td><a href="https://vimcdoc.sourceforge.net/" target="_blank" rel="noreferrer">Vim 中文文档</a></td><td>文档</td><td>中文手册</td></tr><tr><td><a href="https://www.openvim.com/" target="_blank" rel="noreferrer">Open Vim</a></td><td>交互</td><td>网页版练手</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>先做到「能在 Vim 里改完一个文件」再谈效率；</li><li>日常编辑不必强求 Vim，但至少要「不害怕」它——服务器上它常常是唯一选择。</li></ul>',12)])])}const _=t(i,[["render",r]]);export{u as __pageData,_ as default};
